<?php $page_title='Activity Logs';require 'header.php';$detailsColumn=activity_details_column($pdo);$rows=$pdo->query('SELECT l.*, l.'.qi($detailsColumn).' AS log_details, a.name admin_name FROM activity_logs l LEFT JOIN admins a ON a.id=l.admin_id ORDER BY l.created_at DESC LIMIT 500')->fetchAll();?><section class="panel"><h2>Administrator activity</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Administrator</th><th>Action</th><th>Details</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php echo e($r['created_at']); ?></td><td><?php echo e($r['admin_name']?$r['admin_name']:'System'); ?></td><td><?php echo e($r['action']); ?></td><td><?php echo e($r['log_details']); ?></td><td><?php echo e($r['ip_address']); ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php require 'footer.php'; ?>
